 const grid=document.getElementById('mergedResourceGrid');
 const input=document.getElementById('mergedResourceSearch');
 const searchBtn=document.getElementById('mergedResourceSearchBtn');
 const empty=document.getElementById('emptyResource');
 const drawer=document.getElementById('toolDrawer');
 const content=document.getElementById('toolDrawerContent');
 let activeFilter='';

 function esc(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function sentenceCase(v){
   let t=String(v||'').trim().replace(/\s+/g,' ');
   t=t.replace(/(^|[.!?]\s+)([a-z])/g,(m,p,c)=>p+c.toUpperCase());
   t=t.replace(/\bi\b/g,'I');
   t=t.replace(/\btitle i\b/gi,'Title I').replace(/\bgrps\b/gi,'GRPS').replace(/\bmde\b/gi,'MDE').replace(/\bmicip\b/gi,'MICIP').replace(/\blea\b/gi,'LEA').replace(/\bcna\b/gi,'CNA').replace(/\bnexsys\b/gi,'NexSys');
   return t;
 }
 function smartPoints(r,maxItems=8){
   const raw=[r.desc||'',...(r.chunks||[])].filter(Boolean).join(' ')
     .replace(/\s*\|\s*/g,'. ')
     .replace(/\s*[•▪]\s*/g,'. ')
     .replace(/\s+/g,' ')
     .trim();
   if(!raw) return [];
   let candidates=raw.split(/(?<=[.!?])\s+(?=[A-Z0-9“])/)
     .map(x=>sentenceCase(x.replace(/^[.\-–—: ]+|[| ]+$/g,'').trim()))
     .filter(x=>x.length>18);
   const out=[];
   for(const item of candidates){
     if(out.length>=maxItems) break;
     if(item.length<=220){
       if(!out.some(y=>y.toLowerCase()===item.toLowerCase())) out.push(item);
       continue;
     }
     const words=item.split(/\s+/);
     let chunk=[];
     for(const word of words){
       const trial=[...chunk,word].join(' ');
       if(trial.length>190 && chunk.length){
         const text=sentenceCase(chunk.join(' '));
         if(text.length>18 && !out.some(y=>y.toLowerCase()===text.toLowerCase())) out.push(text);
         if(out.length>=maxItems) break;
         chunk=[word];
       } else {
         chunk.push(word);
       }
     }
     if(out.length<maxItems && chunk.length){
       const text=sentenceCase(chunk.join(' '));
       if(text.length>18 && !out.some(y=>y.toLowerCase()===text.toLowerCase())) out.push(text);
     }
   }
   return out.slice(0,maxItems);
 }
 function render(){
   if(!grid)return;
   const q=(input?.value||'').trim().toLowerCase();
   // Word-based search with everyday synonyms, so "field trip" or "paraprofessional" still finds the right tool.
   const SYN={para:['staff'],paras:['staff'],paraprofessional:['staff'],paraprofessionals:['staff'],aide:['staff'],aides:['staff'],interventionist:['staff','intervention'],tutor:['staff','tutor'],tutoring:['tutor','intervention'],salary:['staff'],stipend:['staff','stipend'],employee:['staff'],
     trip:['travel'],trips:['travel'],field:['travel'],excursion:['travel'],conference:['travel','professional learning'],
     food:['food'],snack:['food'],snacks:['food'],meal:['food'],meals:['food'],refreshments:['food'],pizza:['food'],
     reward:['incentive'],rewards:['incentive'],incentives:['incentive'],gift:['incentive'],
     laptop:['technology'],laptops:['technology'],chromebook:['technology'],ipad:['technology'],device:['technology'],devices:['technology'],software:['technology'],
     buy:['purchase'],buying:['purchase'],spend:['spending'],pay:['allowab'],allowable:['allowab'],
     parent:['family'],parents:['family'],caregiver:['family'],caregivers:['family'],families:['family'],
     audit:['monitoring'],visit:['on-site','review'],onsite:['on-site'],review:['monitoring','review'],mde:['mde','monitoring'],
     pd:['professional learning'],training:['professional learning'],
     nonpublic:['private'],
     log:['activity log'],logs:['activity log'],timesheet:['activity log','staff'],effort:['activity log','staff']};
   const STOP=new Set(['a','an','the','and','or','for','to','of','in','on','with','can','i','we','my','our','do','does','is','it','how','what','title','use','using','need']);
   const words=q.split(/[^a-z0-9]+/).filter(w=>w&&!STOP.has(w));
   const hayOf=r=>(r.title+' '+r.desc+' '+r.search+' '+(r.tags||[]).join(' ')).toLowerCase();
   const hit=(hay,w)=>hay.includes(w)||(w.length>4&&hay.includes(w.replace(/s$/,'')))||(SYN[w]||[]).some(x=>hay.includes(x));
   let filtered=RC.filter(r=>{
     const hay=hayOf(r);
     return (!q||hay.includes(q)||(words.length&&words.every(w=>hit(hay,w))))&&(!activeFilter||hay.includes(activeFilter));
   });
   if(q&&filtered.length>1){
     // Rank: words in the title count most, then the description, then the body text.
     const terms=w=>[w].concat(SYN[w]||[]);
     const score=r=>{const t=r.title.toLowerCase(),d=(r.desc||'').toLowerCase(),b=(r.search||'').toLowerCase();let n=(t.includes(q)?12:0)+(d.includes(q)?6:0)+(b.includes(q)?4:0);
       words.forEach(w=>terms(w).forEach(x=>{if(t.includes(x))n+=6;if(d.includes(x))n+=3;n+=Math.min(4,b.split(x).length-1)*0.5;}));return n;};
     filtered=filtered.map(r=>({r,s:score(r)})).sort((a,b)=>b.s-a.s).map(x=>x.r);
   }
   let closest=false;
   if(q&&!filtered.length&&words.length){
     filtered=RC.map(r=>{const hay=hayOf(r);return {r,score:words.filter(w=>hit(hay,w)).length+(words.some(w=>r.title.toLowerCase().includes(w))?1:0)};})
       .filter(x=>x.score>0&&(!activeFilter||hayOf(x.r).includes(activeFilter))).sort((a,b)=>b.score-a.score).slice(0,4).map(x=>x.r);
     closest=filtered.length>0;
   }
   grid.innerHTML=filtered.map(r=>{
     const i=RC.indexOf(r);
     return `<article class="mergedTool"><div class="tags">${(r.tags||[]).slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div><h3>${esc(r.title)}</h3><p>${esc(r.desc||'Open this GRPS Title I tool for the guidance, checklist or next step.')}</p><button type="button" data-tool-index="${i}" onclick="if(window.GRPSOpenTool){window.GRPSOpenTool(${i});} return false;">Open GRPS tool</button></article>`;
   }).join('');
   grid.querySelectorAll('[data-tool-index]').forEach(btn=>{
     btn.addEventListener('click',ev=>{
       ev.preventDefault();
       ev.stopPropagation();
       openTool(Number(btn.dataset.toolIndex));
     });
   });
   if(empty){
     const askUrl='ask-title-i.html?q='+encodeURIComponent((input?.value||'').trim());
     if(closest){
       empty.hidden=false;
       empty.innerHTML='No exact match. These are the closest tools. Still stuck? <a href="'+askUrl+'">Ask Title I Now this question →</a>';
     }else if(!filtered.length){
       empty.hidden=false;
       empty.innerHTML='No matching tool. Try a broader word or choose All'+(q?', or <a href="'+askUrl+'">ask Title I Now this question →</a>':'.');
     }else empty.hidden=true;
   }
 }

 function exampleHTML(r){
   const e=EXAMPLE_UI[r.title]; if(!e) return "";
   const download=TOOL_DOWNLOADS[r.title];
   const downloads=download?`<div class="exampleDownloads">
     <button data-embedded-download="${download.en.split('/').pop()}">Download English Word example ↓</button>
     <button class="spanish" data-embedded-download="${download.es.split('/').pop()}">Descargar ejemplo en español ↓</button>
   </div>`:"";
   const related=`<div class="exampleRelated"><p>Continue with a GRPS tool</p>${e.related.map(t=>`<button data-related-tool="${esc(t)}">${esc(t)} →</button>`).join('')}</div>`;
   let main="";
   if(e.kind==="family"){
     main=`<div class="compareGrid">
       <section class="compareCard weak"><span>EVENT-ONLY DESIGN</span><h3>Family Fun Night</h3><ul><li>Games, raffles, and food drive the event.</li><li>No defined scholar-learning need.</li><li>No specific caregiver learning outcome.</li><li>Success is measured only by attendance.</li></ul></section>
       <section class="compareCard strong"><span>STRONGER TITLE I DESIGN</span><h3>Family Literacy Learning Session</h3><div class="exampleFacts"><div><b>Need</b><p>K–2 reading data show scholars need additional fluency practice.</p></div><div><b>Family outcome</b><p>Families can explain and practice the school’s fluency routine at home.</p></div><div><b>Activity</b><p>Teacher models the routine; families practice; each family leaves with a home-practice tool.</p></div><div><b>Access</b><p>Repeat sessions, translation/interpretation, and other needed supports.</p></div><div><b>Evidence</b><p>Agenda, participation, materials, family feedback, and follow-up.</p></div></div></section>
     </div>
     <div class="designTest"><strong>Quick design test:</strong> Is the activity linked to learning, two-way, accessible, and documented?</div>`;
   } else if(e.kind==="agenda"){
     main=`<div class="agendaList">
       ${[
        ["5 min","Welcome & purpose","Explain why the meeting is being held and what families should leave understanding."],
        ["10 min","What is Title I?","Explain the school’s Title I model and how it supports identified needs."],
        ["10 min","School priorities","Share the needs the school is addressing and the strategies in the school plan."],
        ["10 min","Curriculum, assessment & progress","Explain how scholars are supported and how progress is monitored."],
        ["10 min","Family partnership","Review family engagement, the School-Parent Compact, and ways families can participate."],
        ["10 min","Family voice","Ask what families are seeing, what is working, and what would help scholars be successful."],
        ["5 min","Close & next steps","Explain how feedback will be used and where families can find Title I information."]
       ].map(x=>`<div><span>${x[0]}</span><section><h3>${x[1]}</h3><p>${x[2]}</p></section></div>`).join("")}
     </div>
     <div class="evidenceMini"><strong>Evidence packet</strong><span>Invitation</span><span>Agenda</span><span>Participation record</span><span>Materials</span><span>Family feedback</span><span>Follow-up actions</span></div>`;
   } else if(e.kind==="evidence"){
     const rows=[
       ["Family engagement","Calendar invitation only","Invitation + agenda + participation + materials + feedback + follow-up"],
       ["Title I service","Staff schedule only","Schedule + scholar participation + service log + progress evidence"],
       ["Purchase","Receipt only","Need/plan rationale + approval + coding + invoice/receiving + evidence of use"],
       ["Activity Log","“Met with scholars”","Funded activity + recipient category + actual time + supervisor review"]
     ];
     main=`<div class="evidenceCompare">${rows.map(x=>`<div><b>${x[0]}</b><p class="needsMore"><span>Needs more</span>${x[1]}</p><p class="stronger"><span>Stronger</span>${x[2]}</p></div>`).join("")}</div>
     <div class="designTest"><strong>Evidence test:</strong> Can we show the need, implementation, participation, fiscal trail when applicable, and what happened next?</div>`;
   } else if(e.kind==="evaluation"){
     main=`<div class="compareGrid">
       <section class="compareCard weak"><span>NEEDS MORE</span><h3>“The program was successful.”</h3><ul><li>No implementation evidence.</li><li>No participation evidence.</li><li>No outcome evidence.</li><li>No decision about what should happen next.</li></ul></section>
       <section class="compareCard strong"><span>STRONGER EVALUATION</span><h3>Evidence → Decision</h3><ul><li>What was implemented and with what fidelity?</li><li>Who participated or received the support?</li><li>What changed in the evidence?</li><li>What did spending/fiscal data show?</li><li>Decision: Continue, Change, Stop, or Expand—with rationale.</li></ul></section>
     </div>
     <div class="decisionRow"><span>CONTINUE</span><span>CHANGE</span><span>STOP</span><span>EXPAND</span></div>`;
   } else if(e.kind==="purchase"){
     main=`<div class="purchaseExamples">
       <section><span>EXAMPLE 1 · INSTRUCTIONAL MATERIALS</span><div class="rationaleWeak"><b>Needs more</b><p>“We need reading materials for teachers.”</p></div><div class="rationaleStrong"><b>Stronger rationale</b><p>Reading data identify a specific need; the approved strategy includes supplemental support; the materials are necessary to implement that strategy; coding/allowability will be verified; implementation and progress evidence will be retained.</p></div></section>
       <section><span>EXAMPLE 2 · FAMILY ENGAGEMENT</span><div class="rationaleWeak"><b>Needs more</b><p>“We want supplies and food for a parent night.”</p></div><div class="rationaleStrong"><b>Stronger rationale</b><p>Family feedback and scholar data identify a caregiver-learning need; the activity teaches a specific learning routine; requested materials support that outcome; access and two-way input are built in; evidence and follow-up will be retained.</p></div></section>
     </div>`;
   } else if(e.kind==="scenarios"){
     const rows=[
       ["I want to purchase materials.","Start with the need, connect it to approved work, run the Purchase Pre-Check, verify coding/approval, and keep evidence.","Title I Purchase Pre-Check"],
       ["We want to host a family night.","Define the scholar-learning need and caregiver-learning outcome first. Build two-way engagement, access supports, and evidence.","Family Engagement"],
       ["A Title I-funded employee is covering unrelated duties.","Review the funded role, actual duties, service impact, and documentation requirement. Escalate unresolved alignment questions.","Staffing & Documentation"],
       ["Monitoring is coming and our evidence is scattered.","Organize evidence by review indicator, identify gaps, assign owners/dates, and document corrective action.","Monitoring & On-Site Review"],
       ["A private school requests a purchase.","Confirm the request comes from meaningful consultation and agreed services, check allowability, and route the purchase through GRPS.","Private School Consultation"]
     ];
     main=`<div class="scenarioGrid">${rows.map((x,i)=>`<section><span>${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p><button data-related-tool="${esc(x[2])}">Open ${esc(x[2])} →</button></div></section>`).join("")}</div>`;
   }
   return `<div class="exampleTop"><p>${esc(e.intro)}</p>${downloads}</div>${main}${related}`;
 }


 const TITLE_I_FAQ=[["What is Title I?", "Title I, Part A is federal funding used to help schools address identified academic needs. In GRPS, the work should connect to the school’s needs, approved plan, implementation, evidence, and results.", "What is Title I?"], ["Can Title I pay for this?", "Do not start with the funding source. Start with the identified need and approved strategy. Then determine whether the proposed cost is necessary, reasonable, allowable, properly coded, and approved before the purchase is made.", "Title I Purchase Pre-Check"], ["What does “supplement, not supplant” mean?", "Title I should add to the educational program. It should not replace services or costs GRPS would otherwise be required to provide with state or local resources.", "Title I Decision Tree"], ["What documentation do I need?", "Keep enough evidence to show the full story: the identified need, decision or approval, implementation, participation or service, fiscal record when applicable, results, and any adjustment made.", "What Documentation Do I Need?"], ["Do Title I-funded employees need Activity Logs?", "Use the GRPS Activity Log requirements tied to the employee’s funding and assignment. The log should reflect the actual funded work as it happens, and supervisors should review it for accuracy—not just submission.", "Activity Logs"], ["Can Title I-funded staff cover unrelated duties?", "The assignment must remain aligned to the funded role and current requirements. If duties, funding splits, schedules, or responsibilities change, review the impact before treating the change as routine.", "Staffing & Documentation"], ["What is required for the Annual Title I Meeting?", "Families should understand what Title I means at their school, the needs and priorities being addressed, how resources support the work, and how families can participate and provide input. Keep the required meeting evidence as the work occurs.", "Annual Title I Meeting Builder"], ["What makes a strong Title I family-engagement activity?", "Start with a scholar-learning need and a clear caregiver-learning outcome. Build in two-way participation, access supports, useful take-home learning, and evidence of what occurred and what families said.", "Family Engagement"], ["What should I do before monitoring?", "Use the current review expectations, organize evidence by indicator, identify gaps early, assign an owner and due date, and correct implementation problems before they become monitoring findings.", "Monitoring & On-Site Review"], ["What if the submitted/approved work, staffing, service, or budget changes?", "Review the change before implementation or obligation. Determine whether the plan, budget, coding, consultation, staffing documentation, or application needs to be updated or amended.", "Change & Amendment Workflow"], ["What if I am still not sure?", "Do not guess on allowability, coding, staffing alignment, or compliance. Use the closest GRPS decision tool first; if the issue is still unresolved, route it for Title I or fiscal review before acting.", "Title I Decision Tree"]];
 function faqHTML(){
   const groups=[
     ["Spending",["Can Title I pay for this?","What does “supplement, not supplant” mean?","What if I am still not sure?"]],
     ["Staffing",["Do Title I-funded employees need Activity Logs?","Can Title I-funded staff cover unrelated duties?"]],
     ["Family Engagement",["What is required for the Annual Title I Meeting?","What makes a strong Title I family-engagement activity?"]],
     ["Planning & Monitoring",["What is Title I?","What documentation do I need?","What should I do before monitoring?","What if the submitted/approved work, staffing, service, or budget changes?"]]
   ];
   return `<div class="faqIntro"><p>Choose the question you have. Each answer is short and takes you directly to the GRPS tool for the next step.</p></div>`+
   groups.map(g=>`<section class="faqGroup"><h3>${g[0]}</h3>${g[1].map(q=>{const x=TITLE_I_FAQ.find(v=>v[0]===q);return `<details class="faqItem"><summary>${esc(x[0])}<span>+</span></summary><div class="faqAnswer"><p>${esc(x[1])}</p><button data-related-tool="${esc(x[2])}">Open ${esc(x[2])} →</button></div></details>`}).join("")}</section>`).join("");
 }


