 function classifyResource(r){
   const t=r.title||"";
   if(t==="Help & Contacts") return "contact";
   if(t==="Private School Consultation") return "privateSchoolConsultation";
   if(t==="Title I FAQ") return "faq";
   if(t==="Evidence Checklists by Activity") return "evidenceByActivity";
   if(EXAMPLE_UI[t]) return "example";
   if(TOOL_DOWNLOADS[t]) return "download";
   if(/Checklist|Risk Check|Self-Assessment|Year-End Closeout/i.test(t)) return "checklist";
   if(/Decision Tree|Can I Buy This|Change & Amendment Workflow|Builder/i.test(t)) return "decision";
   if(/Important Dates|Current Title I Updates|What is Title I|Resource Library|Professional Learning Path|New Staff Quick Start|Equitable Services/i.test(t)) return "reference";
   if(/Dashboard|Who Owns What|Program & Instructional Staff/i.test(t)) return "role";
   if(/30-Minute|Monthly Building Routine/i.test(t)) return "meeting";
   if(/Monitoring|On-Site Review|Evidence Structure|What Documentation/i.test(t)) return "monitoring";
   return "guidance";
 }
 function checklistHTML(r){
   const items=smartPoints(r,9);
   return `<p class="toolIntro">${esc(r.desc||"Use this GRPS checklist before moving forward.")}</p><section class="interactiveCheck"><h3>Check before you move forward</h3>${items.map((x,i)=>`<label><input type="checkbox"><span><b>${i+1}</b>${esc(x)}</span></label>`).join("")}<div class="checkDecision">If an item is unclear or cannot be checked, resolve it before treating the work as complete.</div></section>`;
 }
 function evidenceByActivityHTML(){
   const groups=[
    ["Purchase / Contracted Service",["Identified need and connection to the approved plan/strategy","Allowability rationale and required approval","Quote, contract, purchase documentation, or procurement record as applicable","Function/object coding and payment record","Evidence the item or service was received and used for the approved purpose","Outcome or implementation evidence when applicable"]],
    ["Family Engagement Activity",["Learning need and intended caregiver outcome","Invitation or communication","Agenda and learning materials","Participation or sign-in record","Translation, interpretation, or other access supports as applicable","Family feedback or input","Fiscal records for Title I-funded costs","Follow-up or evaluation"]],
    ["Title I-Funded Staff",["Approved job description or assignment","Funding information","Schedule, service log, caseload, or role-appropriate implementation evidence","Required activity/time documentation","Supervision or evaluation records as applicable","Evidence of impact or connection to the approved strategy"]],
    ["Academic Intervention / Program",["Need/data used to identify the strategy","Approved plan or activity","Scholar selection or participation criteria where applicable","Service schedule and implementation/fidelity evidence","Progress-monitoring or outcome data","Evaluation and adjustment decision"]],
    ["Annual Title I Meeting",["Invitation or outreach evidence","Agenda","Presentation and handouts","Participation record","Current family engagement policy/plan and School-Parent Compact materials","Questions, family input, and response/follow-up","Evaluation or feedback","Fiscal records if Title I funds were used"]]
   ];
   return `<p class="toolIntro">Choose the activity. The checklist will show only the evidence that belongs with that work.</p>
   <div class="evidencePicker" style="display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 20px">${groups.map((g,i)=>`<button type="button" onclick="selectEvidenceType(${i})" id="evbtn${i}" style="border:1px solid #c9d8e6;background:${i===0?'#0b3a66':'#fff'};color:${i===0?'#fff':'#0b3a66'};border-radius:999px;padding:10px 14px;font-weight:800;cursor:pointer">${g[0]}</button>`).join('')}</div>
   ${groups.map((g,i)=>`<section id="evpanel${i}" class="interactiveCheck evidencePanel" style="${i?'display:none;':''}"><div style="display:flex;justify-content:space-between;gap:16px;align-items:start"><div><p class="eyebrow" style="margin:0 0 5px">EVIDENCE TO RETAIN</p><h3 style="margin:0 0 8px">${g[0]}</h3></div><button type="button" onclick="resetEvidence(${i})" style="border:0;background:transparent;color:#526b80;font-weight:800;cursor:pointer">Reset</button></div><p style="margin:0 0 14px;color:#526b80">Check items as you file them. This is an evidence organizer—not another approval form.</p>${g[1].map((x,j)=>`<label><input type="checkbox" data-ev="${i}-${j}"><span>${x}</span></label>`).join('')}<div class="checkDecision"><b>Before you close this activity:</b> The evidence should tell the full story—why the work was needed, what happened, who participated or received the support, what was spent when applicable, and what happened next.</div></section>`).join('')}`;
 }
 function selectEvidenceType(n){
   document.querySelectorAll('.evidencePanel').forEach((p,i)=>p.style.display=i===n?'block':'none');
   document.querySelectorAll('.evidencePicker button').forEach((b,i)=>{b.style.background=i===n?'#0b3a66':'#fff';b.style.color=i===n?'#fff':'#0b3a66';});
 }
 function resetEvidence(n){document.querySelectorAll(`#evpanel${n} input[type="checkbox"]`).forEach(x=>x.checked=false);}
 window.selectEvidenceType=selectEvidenceType;
 window.resetEvidence=resetEvidence;
